#include "/src/lcms/include/lcms2.h"
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define MAX_STR_LEN 32

int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
    if (Size < 1) {
        return 0;
    }

    cmsContext ctx = cmsCreateContext(NULL, NULL);
    if (!ctx) {
        return 0;
    }

    /*
     * ANALYSIS: The function cmsIT8LoadFromMem is only tested with valid
     *           data generated by cmsIT8SaveToMem. This misses many
     *           error-handling code paths in the parser.
     * IMPLEMENTATION: We first call cmsIT8LoadFromMem with the raw fuzzer
     *                 input. This will test the parser with a wide range of
     *                 malformed and unexpected data, increasing coverage in
     *                 error-handling branches.
     */
    cmsHANDLE hIT8_loaded_raw = cmsIT8LoadFromMem(ctx, Data, Size);
    if (hIT8_loaded_raw) {
        cmsIT8Free(hIT8_loaded_raw);
    }

    cmsHANDLE hIT8 = cmsIT8Alloc(ctx);
    if (!hIT8) {
        cmsDeleteContext(ctx);
        return 0;
    }

    size_t data_offset = 0;

    /*
     * ANALYSIS: The function-level coverage report showed cmsIT8SetTableByLabel
     *           had very low coverage. The detailed fuzz target report showed the call
     *           to cmsIT8SetData always failed because the input size check was too
     *           restrictive, leaving subsequent code uncovered.
     * IMPLEMENTATION: The size check has been relaxed by reducing MAX_STR_LEN.
     *                 The following code block first calls cmsIT8SetTableByLabel
     *                 to define the table structure. This allows the subsequent call
     *                 to cmsIT8SetData to succeed, exercising previously-uncovered
     *                 code paths.
     */
    if (Size - data_offset >= 3 * MAX_STR_LEN) {
        char patch[MAX_STR_LEN];
        char sample[MAX_STR_LEN];
        char value[MAX_STR_LEN];

        memcpy(patch, Data + data_offset, MAX_STR_LEN);
        data_offset += MAX_STR_LEN;
        memcpy(sample, Data + data_offset, MAX_STR_LEN);
        data_offset += MAX_STR_LEN;
        memcpy(value, Data + data_offset, MAX_STR_LEN);
        data_offset += MAX_STR_LEN;

        patch[MAX_STR_LEN - 1] = '\0';
        sample[MAX_STR_LEN - 1] = '\0';
        value[MAX_STR_LEN - 1] = '\0';

        // Define the table structure before trying to set data in it.
        cmsIT8SetTableByLabel(hIT8, "D50", "SAMPLE_ID", "RGB_R");

        if (cmsIT8SetData(hIT8, patch, sample, value)) {
            /*
             * ANALYSIS: The function-level coverage report showed cmsIT8GetPatchName
             *           and cmsIT8GetDataDbl have low coverage.
             * IMPLEMENTATION: After successfully setting data, call these functions
             *                 to exercise their logic for retrieving data from a
             *                 populated IT8 handle.
             */
            cmsIT8GetPatchName(hIT8, 0, NULL);
            double d;
            d = cmsIT8GetDataDbl(hIT8, patch, sample);
        }
    }

    /*
     * ANALYSIS: The function-level coverage report showed cmsIT8SetPropertyMulti
     *           and cmsIT8EnumPropertyMulti have 0% coverage.
     * IMPLEMENTATION: Call these functions to exercise their logic.
     */
    cmsIT8SetPropertyMulti(hIT8, "MyProp", "Val1", "Val2");
    const char **SubpropertyNames;
    cmsIT8EnumPropertyMulti(hIT8, "MyProp", &SubpropertyNames);


    /*
     * ANALYSIS: The coverage report for cmsIT8SaveToMem showed that the branch
     *           at line 2056 `if (sd.Base && (*BytesNeeded > 0))` never had
     *           `*BytesNeeded` as 0.
     * IMPLEMENTATION: To cover this branch, we will sometimes call
     *                 cmsIT8SaveToMem with *BytesNeeded set to 0.
     */
    cmsUInt32Number bytes_needed = 0;
    if (Size > 0 && (Data[0] % 2) == 0) {
        // Let bytes_needed be 0 to hit the uncovered branch.
    } else {
        cmsIT8SaveToMem(hIT8, NULL, &bytes_needed);
    }

    if (bytes_needed > 0) {
        char *mem_buffer = (char *)malloc(bytes_needed);
        if (mem_buffer) {
            if (cmsIT8SaveToMem(hIT8, mem_buffer, &bytes_needed)) {
                /*
                 * ANALYSIS: The function cmsIT8LoadFromMem has several error-handling
                 *           paths that are not covered. It also has complex parsing logic.
                 * IMPLEMENTATION: We use the data generated by cmsIT8SaveToMem to test
                 *                 cmsIT8LoadFromMem. This provides valid (and near-valid)
                 *                 input to thoroughly test the parsing logic.
                 */
                cmsHANDLE hIT8_loaded = cmsIT8LoadFromMem(ctx, (const void *)mem_buffer, bytes_needed);
                if (hIT8_loaded) {
                    cmsIT8Free(hIT8_loaded);
                }
            }
            free(mem_buffer);
        }
    }

    cmsIT8Free(hIT8);

    /*
     * ANALYSIS: The function-level coverage report showed that many Type_*_Read/Write
     *           functions in cmstypes.c have zero coverage.
     * IMPLEMENTATION: Create a placeholder profile and write/read a cmsSigUcrBgTag
     *                 to exercise the Type_UcrBg_Read and Type_UcrBg_Write handlers.
     */
    cmsHPROFILE hProfile = cmsCreateProfilePlaceholder(ctx);
    if (hProfile) {
        cmsUcrBg ucrbg;
        ucrbg.Ucr = cmsBuildTabulatedToneCurve16(ctx, 1, NULL);
        ucrbg.Bg = cmsBuildTabulatedToneCurve16(ctx, 1, NULL);
        cmsMLU *desc = cmsMLUalloc(ctx, 1);
        cmsMLUsetASCII(desc, "en", "US", "test");
        ucrbg.Desc = desc;

        if (ucrbg.Ucr && ucrbg.Bg && ucrbg.Desc) {
            cmsWriteTag(hProfile, cmsSigUcrBgTag, &ucrbg);
            cmsReadTag(hProfile, cmsSigUcrBgTag);
        }

        if (ucrbg.Ucr) cmsFreeToneCurve(ucrbg.Ucr);
        if (ucrbg.Bg) cmsFreeToneCurve(ucrbg.Bg);
        if (desc) cmsMLUfree(desc);

        /*
         * ANALYSIS: The function-level coverage report showed that many Type_*
         *           functions in cmstypes.c have zero coverage. Specifically,
         *           Type_Chromaticity_Read/Write and Type_Text_Write were identified
         *           as having no coverage.
         * IMPLEMENTATION: Add calls to cmsWriteTag/cmsReadTag with
         *                 cmsSigChromaticityTag and cmsSigCharTargetTag to exercise
         *                 these uncovered type handlers.
         */
        cmsCIEXYZTRIPLE xyz_triple;
        xyz_triple.Red.X = 0.1; xyz_triple.Red.Y = 0.2; xyz_triple.Red.Z = 0.3;
        xyz_triple.Green.X = 0.4; xyz_triple.Green.Y = 0.5; xyz_triple.Green.Z = 0.6;
        xyz_triple.Blue.X = 0.7; xyz_triple.Blue.Y = 0.8; xyz_triple.Blue.Z = 0.9;
        cmsWriteTag(hProfile, cmsSigChromaticityTag, &xyz_triple);
        cmsReadTag(hProfile, cmsSigChromaticityTag);

        cmsMLU *charTargetDesc = cmsMLUalloc(ctx, 1);
        if (charTargetDesc) {
            cmsMLUsetASCII(charTargetDesc, "en", "US", "test");
            cmsWriteTag(hProfile, cmsSigCharTargetTag, charTargetDesc);
            cmsReadTag(hProfile, cmsSigCharTargetTag);
            cmsMLUfree(charTargetDesc);
        }

        /*
         * ANALYSIS: The function-level coverage report showed
         *           cmsDetectDestinationBlackPoint has low coverage (34%).
         * IMPLEMENTATION: Call the function with the created placeholder profile
         *                 to improve its coverage.
         */
        cmsCIEXYZ black_point;
        cmsDetectDestinationBlackPoint(&black_point, hProfile, INTENT_PERCEPTUAL, 0);


        cmsCloseProfile(hProfile);
    }

    /*
     * ANALYSIS: The function-level coverage report showed cmsCreateBCHSWabstractProfile
     *           has 0% coverage.
     * IMPLEMENTATION: Call the function with some default arguments to exercise it.
     *                 The returned profile must be closed to prevent memory leaks.
     */
    cmsHPROFILE bchswProfile = cmsCreateBCHSWabstractProfile(16, 0.0, 0.0, 0.0, 0.0, 5000, 5000);
    if (bchswProfile) {
        cmsCloseProfile(bchswProfile);
    }

    /*
     * ANALYSIS: The function-level coverage report showed cmsCreateRGBProfile
     *           has 0% coverage.
     * IMPLEMENTATION: Call the function with valid arguments to exercise it.
     *                 The white point and primaries are arbitrary but valid. The tone
     *                 curves are created and must be freed. The returned profile must
     *                 be closed to prevent memory leaks.
     */
    cmsCIExyY whitePoint = { 0.3127, 0.3290, 1.0 };
    cmsCIExyYTRIPLE primaries = { { 0.64, 0.33, 1.0 }, { 0.30, 0.60, 1.0 }, { 0.15, 0.06, 1.0 } };
    cmsToneCurve* curves[3];
    curves[0] = cmsBuildGamma(ctx, 2.2);
    curves[1] = cmsBuildGamma(ctx, 2.2);
    curves[2] = cmsBuildGamma(ctx, 2.2);

    if (curves[0] && curves[1] && curves[2]) {
        cmsHPROFILE rgbProfile = cmsCreateRGBProfile(&whitePoint, &primaries, curves);
        if (rgbProfile) {
            cmsCloseProfile(rgbProfile);
        }
    }

    if (curves[0]) cmsFreeToneCurve(curves[0]);
    if (curves[1]) cmsFreeToneCurve(curves[1]);
    if (curves[2]) cmsFreeToneCurve(curves[2]);


    cmsDeleteContext(ctx);

    return 0;
}